<script setup>
import { ref } from 'vue'

const props = defineProps({ organizations: { type: Array, default: () => [] }, selectedOrganizationID: { type: Number, default: 0 } })
const emit = defineEmits(['create', 'select', 'refresh', 'visibility'])
const dialogOpen = ref(false)
const form = ref({ name: '', code: '', parent_id: 0 })
function openCreate() { form.value = { name: '', code: '', parent_id: 0 }; dialogOpen.value = true }
function submit() { emit('create', { ...form.value, parent_id: Number(form.value.parent_id) || 0 }); dialogOpen.value = false }
</script>

<template>
  <section class="page-stack">
    <article class="panel">
      <header class="panel-heading panel-actions-only"><div class="heading-actions"><button class="primary" type="button" @click="openCreate">＋ 新建组织</button><button class="text-button" type="button" @click="emit('refresh')">刷新</button></div></header>
      <ul class="list"><li v-for="organization in props.organizations" :key="organization.ID" :class="{ selected: organization.ID === selectedOrganizationID }"><div class="organization-row"><button class="organization-select" type="button" @click="emit('select', organization.ID)"><span class="tree-mark">{{ organization.parent_id ? '↳' : '●' }}</span><div><strong>{{ organization.name }}</strong><small>{{ organization.code }} · {{ organization.is_visible ? '公开可申请' : '隐藏' }}</small></div></button><label class="visibility" @click.stop><input type="checkbox" :checked="organization.is_visible" @change="emit('visibility', { id: organization.ID, visible: $event.target.checked })" /><span>公开</span></label><em v-if="organization.ID === selectedOrganizationID">当前</em></div></li><li v-if="!props.organizations.length" class="muted">尚未创建组织。</li></ul>
    </article>
    <div v-if="dialogOpen" class="modal-backdrop" @click.self="dialogOpen = false"><section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="organization-dialog-title"><header class="modal-heading"><div><p>ORGANIZATION</p><h2 id="organization-dialog-title">新建组织</h2></div><button class="icon-button" type="button" aria-label="关闭" @click="dialogOpen = false">×</button></header><form class="form-stack" @submit.prevent="submit"><label>组织名称<input v-model="form.name" required maxlength="128" placeholder="例如：综合管理部" /></label><label>组织代码<input v-model="form.code" required maxlength="64" placeholder="例如：general-office" /></label><label>上级组织<select v-model="form.parent_id"><option :value="0">无（一级组织）</option><option v-for="organization in props.organizations" :key="organization.ID" :value="organization.ID">{{ organization.name }}</option></select></label><footer class="modal-actions"><button class="ghost" type="button" @click="dialogOpen = false">取消</button><button class="primary" type="submit">创建组织</button></footer></form></section></div>
  </section>
</template>

<style scoped>
.page-stack{display:grid;gap:20px}.panel{padding:26px;border:1px solid #dce5df;border-radius:12px;background:#fff;box-shadow:0 10px 28px rgba(30,58,44,.05)}.panel-heading,.modal-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}.panel-heading{align-items:center;margin-bottom:14px}.panel-heading p,.modal-heading p{margin:0;color:#5c796c;font-size:11px;font-weight:800;letter-spacing:.12em}.panel-heading h2,.modal-heading h2{margin:6px 0 0;color:#173f31;font-size:22px}.heading-actions,.modal-actions{display:flex;align-items:center;gap:10px}.helper{margin:0 0 18px;color:#65766d;font-size:13px;line-height:1.65}.list{display:grid;gap:8px;margin:0;padding:0;list-style:none}.list li{border:1px solid #e4ece6;border-radius:9px;background:#fbfdfb}.list li.selected{border-color:#a9ceb8;background:#f2f9f4}.organization-row{display:flex;align-items:center;gap:12px;min-height:66px;padding:8px 14px}.organization-select{display:flex;min-width:0;flex:1;align-items:center;gap:12px;padding:6px 0;border:0;color:inherit;background:transparent;text-align:left}.organization-select>div{min-width:0}.organization-select strong,.organization-select small{display:block}.organization-select strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.organization-select small{margin-top:4px;color:#76877e;font-size:12px}.tree-mark{color:#4e9474}.visibility{display:inline-flex;align-items:center;gap:6px;color:#61776b;font-size:12px;font-weight:650;white-space:nowrap;cursor:pointer}.visibility input{width:15px;height:15px;accent-color:#17634e}.organization-row em{padding:4px 8px;border-radius:999px;color:#28614c;background:#e6f3e9;font-size:12px;font-style:normal;font-weight:700}.muted{padding:42px 0;border:0!important;color:#7a8981;text-align:center}.primary,.ghost,.text-button,.icon-button{font:inherit;cursor:pointer}.primary{min-height:40px;padding:0 14px;border:0;border-radius:8px;color:#fff;background:#1e6956;font-weight:700}.primary:hover{background:#155642}.ghost{min-height:40px;padding:0 14px;border:1px solid #bfd4c7;border-radius:8px;color:#176851;background:#fff;font-weight:700}.text-button{border:0;color:#1b6854;background:none;font-weight:700}.modal-backdrop{position:fixed;z-index:60;inset:0;display:grid;place-items:center;padding:20px;background:rgba(14,28,22,.46)}.modal-card{width:min(680px,calc(100vw - 40px));padding:30px 34px;border-radius:14px;background:#fff;box-shadow:0 24px 72px rgba(0,0,0,.22)}.icon-button{display:grid;width:32px;height:32px;place-items:center;border:0;border-radius:7px;color:#52645a;background:#eff3f0;font-size:23px;line-height:1}.form-stack{display:grid;gap:16px;margin-top:22px}.form-stack label{display:grid;gap:7px;color:#4d6258;font-size:13px;font-weight:650}.form-stack input,.form-stack select{width:100%;min-height:44px;padding:0 12px;border:1px solid #cfdcd3;border-radius:8px;color:#192820;background:#fff;outline:none}.form-stack input:focus,.form-stack select:focus{border-color:#26705b;box-shadow:0 0 0 3px rgba(38,112,91,.12)}.modal-actions{justify-content:flex-end;padding-top:4px}@media(max-width:600px){.panel{padding:20px}.heading-actions{gap:8px}.heading-actions .primary{padding:0 10px}.organization-row{align-items:flex-start;flex-wrap:wrap}.organization-select{min-width:calc(100% - 20px)}.visibility{margin-left:28px}.organization-row em{margin-left:auto}.modal-card{width:calc(100vw - 32px);padding:24px 20px}}
</style>
